// Some portions generated by Claude
// Captures every Workbench route for visual review (before/after comparisons for
// .agent/execplans/workbench-app-shell-and-critique-fixes-20260930.md).
// Usage from the repository root, with a running preview and the seeded "bsbm" repository:
//     OUT=/tmp/wb-shots CONFIGS=desktop-light,desktop-dark,mobile-light node design/workbench-app-shell-plan-20260930/capture-routes.cjs
// Environment: WB (default http://127.0.0.1:18090/rdf4j-workbench), OUT (required), CONFIGS, ONLY (comma separated route keys).
const path = require('node:path');
const fs = require('node:fs');
const { chromium } = require(path.resolve(__dirname, '../../e2e/node_modules/playwright'));

const WB = (process.env.WB || 'http://127.0.0.1:18090/rdf4j-workbench').replace(/\/+$/, '') + '/repositories';
const OUT = process.env.OUT;
if (!OUT) {
	throw new Error('Set OUT to an output directory');
}
const product1 = encodeURIComponent('<http://www4.wiwiss.fu-berlin.de/bizer/bsbm/v01/instances/dataFromProducer1/Product1>');
const routes = [
	['server', '/NONE/server'], ['repositories', '/NONE/repositories'], ['create', '/NONE/create'], ['delete', '/NONE/delete'],
	['summary', '/bsbm/summary'], ['namespaces', '/bsbm/namespaces'], ['contexts', '/bsbm/contexts'], ['types', '/bsbm/types'],
	['explore', '/bsbm/explore?resource=' + product1], ['query', '/bsbm/query'], ['saved-queries', '/bsbm/saved-queries'],
	['export', '/bsbm/export'], ['update', '/bsbm/update'], ['add', '/bsbm/add'], ['remove', '/bsbm/remove'],
	['clear', '/bsbm/clear'], ['information', '/bsbm/information'], ['missing', '/nope/summary']
];
const viewports = { desktop: { width: 1440, height: 900 }, tablet: { width: 768, height: 1024 }, mobile: { width: 390, height: 844 } };

(async () => {
	fs.mkdirSync(OUT, { recursive: true });
	const only = process.env.ONLY ? process.env.ONLY.split(',') : null;
	const browser = await chromium.launch();
	for (const config of (process.env.CONFIGS || 'desktop-light').split(',')) {
		const [viewport, colorScheme] = config.split('-');
		const context = await browser.newContext({ viewport: viewports[viewport], colorScheme });
		const page = await context.newPage();
		for (const [key, route] of routes) {
			if (only && !only.includes(key)) {
				continue;
			}
			const response = await page.goto(WB + route, { waitUntil: 'networkidle' }).catch(error => ({ status: () => String(error) }));
			await page.waitForTimeout(400);
			const file = path.join(OUT, `${config}-${key}.png`);
			await page.screenshot({ path: file });
			console.log(config, key, response && response.status(), 'title=' + JSON.stringify(await page.title()));
		}
		await context.close();
	}
	await browser.close();
})();
